def count_special_numbers(n_bin, k):
    n = int(n_bin, 2)
    length = len(n_bin)

    # dp[pos][count][ops] = number of ways to form a number with 'pos' bits,
    # 'count' number of set bits, and 'ops' operations to reach 1
    dp = [[[0] * (k + 1) for _ in range(length + 1)] for _ in range(length + 1)]

    # Base case: one way to have a number with 0 bits and 0 operations
    dp[0][0][0] = 1

    for pos in range(length):
        for count in range(length):
            for ops in range(k + 1):
                if dp[pos][count][ops] == 0:
                    continue

                # Case 1: Add a 0 bit
                dp[pos + 1][count][ops] = (dp[pos + 1][count][ops] + dp[pos][count][ops]) % MOD

                # Case 2: Add a 1 bit
                if ops < k:
                    dp[pos + 1][count + 1][ops + 1] = (dp[pos + 1][count + 1][ops + 1] + dp[pos][count][ops]) % MOD

    result = 0
    for count in range(1, length + 1):
        if count >= k:
            result = (result + dp[length][count][k]) % MOD

    return result

def main():
